import{_ as t,o as r,c as a,a0 as n}from"./chunks/framework.Dl6s926z.js";const h=JSON.parse('{"title":"Variable: grammar","description":"","frontmatter":{},"headers":[],"relativePath":"api/reference/cst/xml-grammar/variables/grammar.md","filePath":"api/reference/cst/xml-grammar/variables/grammar.md"}'),o={name:"api/reference/cst/xml-grammar/variables/grammar.md"};function l(i,e,s,c,m,w){return r(),a("div",null,[...e[0]||(e[0]=[n('<p><a href="./../../../README.html"><strong>@miy2/xml-api</strong></a></p><hr><h1 id="variable-grammar" tabindex="-1">Variable: grammar <a class="header-anchor" href="#variable-grammar" aria-label="Permalink to &quot;Variable: grammar&quot;">​</a></h1><blockquote><p><code>const</code> <strong>grammar</strong>: <a href="./../../grammar/classes/Grammar.html"><code>Grammar</code></a></p></blockquote><p>Unimplemented Well-formedness Constraints (WFC)</p><p>The following constraints are currently not enforced by this parser. Implementation would require an Entity Manager, DTD Processor, and extended Context.</p><ul><li><p>[WFC: PEs in Internal Subset] &quot;In the internal DTD subset, parameter-entity references MUST NOT occur within markup declarations...&quot; <a href="https://www.w3.org/TR/xml/#wfc-PEinInternalSubset" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#wfc-PEinInternalSubset</a></p></li><li><p>[WFC: External Subset] &quot;The external subset, if any, MUST match the production for extSubset.&quot; <a href="https://www.w3.org/TR/xml/#ExtSubset" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#ExtSubset</a></p></li><li><p>[WFC: PE Between Declarations] &quot;The replacement text of a parameter entity reference in a DeclSep MUST match the production extSubsetDecl.&quot; <a href="https://www.w3.org/TR/xml/#PE-between-Decls" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#PE-between-Decls</a></p></li><li><p>[WFC: No External Entity References] &quot;Attribute values MUST NOT contain direct or indirect entity references to external entities.&quot; <a href="https://www.w3.org/TR/xml/#NoExternalRefs" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#NoExternalRefs</a></p></li><li><p>[WFC: No &lt; in Attribute Values] &quot;The replacement text of any entity referred to directly or indirectly in an attribute value MUST NOT contain a &lt;.&quot; <a href="https://www.w3.org/TR/xml/#CleanAttrVals" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#CleanAttrVals</a></p></li><li><p>[WFC: Entity Declared] &quot;In a document without any DTD, a document with only an internal DTD subset which contains no parameter entity references, or a document with standalone=&#39;yes&#39;, for an entity reference that does not occur within the external subset or a parameter entity, the Name given in the entity reference MUST match that in an entity declaration...&quot; <a href="https://www.w3.org/TR/xml/#wf-entdeclared" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#wf-entdeclared</a></p></li><li><p>[WFC: Parsed Entity] &quot;An internal general parsed entity MUST match the production content.&quot; <a href="https://www.w3.org/TR/xml/#textent" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#textent</a></p></li><li><p>[WFC: No Recursion] &quot;A parsed entity MUST NOT contain a recursive reference to itself, either directly or indirectly.&quot; <a href="https://www.w3.org/TR/xml/#norecursion" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#norecursion</a></p></li><li><p>[WFC: In DTD] &quot;Parameter-entity references MUST NOT occur outside the DTD.&quot; <a href="https://www.w3.org/TR/xml/#indtd" target="_blank" rel="noreferrer">https://www.w3.org/TR/xml/#indtd</a></p></li></ul>',7)])])}const u=t(o,[["render",l]]);export{h as __pageData,u as default};
